const fs = require('fs');

class Scanner {
    constructor(input) {
        this.tokens = input.trim().split(/\s+/).reverse();
    }

    token() {
        return this.tokens.pop();
    }

    tokenNumber() {
        return Number(this.token());
    }
}

function factorize(n) {
    let ans = [];
    let d = 2;
    while (d * d <= n) {
        while (n % d === 0) {
            ans.push(d);
            n = Math.floor(n / d);
        }
        d += 1;
    }
    if (n > 1) {
        ans.push(n);
    }
    return ans;
}

function solve(scan) {
    const n = scan.tokenNumber();
    const k = scan.tokenNumber();

    const factors = factorize(n);
    const num_factors = factors.length;
    if (num_factors < k) {
        console.log("-1");
        return;
    }

    let output = [];
    for (let i = 0; i < k - 1; i++) {
        output.push(String(factors[i]));
    }
    let last_factor = 1;
    for (let i = k - 1; i < num_factors; i++) {
        last_factor *= factors[i];
    }
    output.push(String(last_factor));
    console.log(output.join(' '));
}

function main() {
    const input = fs.readFileSync(0, 'utf8');
    const scan = new Scanner(input);
    solve(scan);
}

main();

